//   Course Clips/ C - Castle/Castle Inside/ Section C & D/C-13 Front GFX Clip / layer 'Layer 2' / frame 1
void frame_3234_0(Activation& scope) {
    scope["played"] = false;
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        scope["AL"]();
        if (_root["Course"]["BackGFX"]["inroom"] == true && scope["_alpha"] > 0) {
            //
            if (scope["played"] == false) {
                _root["StartNewMusicAndIntroNoVar"]("BowserPlan-Intro", "BowserPlan-Repeat");
            }
            scope["played"] = true;
            //
            _root["Course"]["Platforms"]["gotoAndStop"](2);
            scope["AL"] = scope.function([](Activation& scope) -> Value {
                if (scope["_alpha"] <= 0) {
                    scope["_alpha"] = 0;
                    scope["AL"] = Value::null();
                } else {
                    scope["_alpha"] -= 2;
                }
                return undefined;
            });
        } else if (strictNotEquals(_root["Course"]["BackGFX"]["inroom"], true) && scope["_alpha"] < 100) {
            //
            if (scope["played"] == true) {
                _root["StartNewMusicAndIntroNoVar"]("InsidetheCastleWalls");
            }
            scope["played"] = false;
            //
            _root["Course"]["Platforms"]["gotoAndStop"](1);
            scope["AL"] = scope.function([](Activation& scope) -> Value {
                if (scope["_alpha"] >= 100) {
                    scope["_alpha"] = 100;
                    scope["AL"] = Value::null();
                } else {
                    scope["_alpha"] += 2;
                }
                return undefined;
            });
        }
        return undefined;
    });
}

