//   Course Clips/ M - Mini Courses / M2 - Wet Dry World/M2-1 Switch PL 1 / layer 'Layer 2' / frame 2
void frame_7044_1(Activation& scope) {
    scope["depth"] = _root["Course"]["Platforms"]["getNextHighestDepth"]();
    scope["itemname"] = "M2-1-SPL1" + scope["depth"];
    _root["Course"]["Platforms"]["attachMovie"]("M2-1-SPL1", scope["itemname"], scope["depth"], obj({}));
    // Activated Sound fx
    _root["Mariosound"] = new_(Sound, scope.self);
    _root["Mariosound"]["attachSound"]("Tick");
    _root["Mariosound"]["start"](0, 1);
    _root["Mariosound"]["setVolume"](_root["MarioVolume"]);
    //
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        if (scope["_alpha"] <= 100 && scope["count"] < scope["duration"]) {
            scope["_alpha"] += 20;
            scope["_alpha"] = Math["min"](scope["_alpha"], 100);
        }
        scope["count"]++;
        if ((scope["count"] / scope["wait"]) == Math["round"](scope["count"] / scope["wait"])) {
            if (scope["count"] > (0.5) * scope["duration"]) {
                scope["wait"] = 16;
                if (scope["count"] > (0.75) * scope["duration"]) {
                    scope["wait"] = 8;
                    scope["_alpha"] = 60;
                }
                if (scope["count"] > (0.9) * scope["duration"]) {
                    scope["wait"] = 4;
                    scope["_alpha"] = 40;
                }
            }
            _root["Mariosound"] = new_(Sound, scope.self);
            _root["Mariosound"]["attachSound"]("Tick");
            _root["Mariosound"]["start"](0, 1);
            _root["Mariosound"]["setVolume"](_root["MarioVolume"]);
        }
        if (scope["count"] > scope["duration"]) {
            scope["wait"] = scope["duration"];
            scope["_alpha"] -= 10;
            if (scope["_alpha"] <= 0) {
                scope["count"] = 0;
                _root["Course"]["Platforms"][scope["itemname"]]["removeMovieClip"]();
                prevFrame();
            }
        }
        return undefined;
    });
}

